changeSet.sql:
ALTER TABLE account ADD COLUMN authority_generation bigint DEFAULT 0 NOT NULL,
    ADD CONSTRAINT ck_account_authority_generation CHECK (authority_generation >= 0);
CREATE FUNCTION ai_choice_narrows_authority() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.ai_choice IS DISTINCT FROM OLD.ai_choice
       AND (NEW.ai_choice IS NULL
            OR NEW.ai_choice = 'NO_AI'
            OR (NEW.ai_choice = 'IN_HOUSE_ONLY' AND OLD.ai_choice = 'CLOUD')) THEN
        NEW.authority_generation := OLD.authority_generation + 1;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER account_ai_choice_narrows_authority BEFORE UPDATE OF ai_choice ON account
    FOR EACH ROW EXECUTE FUNCTION ai_choice_narrows_authority();

rollback.sql:
