    AND jsonb_typeof(authorization_stamp -> 'workspace') = 'number'
    AND (authorization_stamp ->> 'workspace') ~ '^[0-9]{1,19}$'
    AND (authorization_stamp ->> 'workspace')::numeric <= 9223372036854775807) IS TRUE);
